# RGB -> gri, YCbCr, HSV
def gri(r, g, b):
    return 0.299 * r + 0.587 * g + 0.114 * b


def ycbcr(r, g, b):
    return (gri(r, g, b),
            128 - 0.168736 * r - 0.331264 * g + 0.5 * b,
            128 + 0.5 * r - 0.418688 * g - 0.081312 * b)


def hsv(r, g, b):
    rp, gp, bp = r / 255, g / 255, b / 255
    mx, mn = max(rp, gp, bp), min(rp, gp, bp)
    d = mx - mn
    if d == 0:
        h = 0.0
    elif mx == rp:
        h = 60 * (((gp - bp) / d) % 6)
    elif mx == gp:
        h = 60 * ((bp - rp) / d + 2)
    else:
        h = 60 * ((rp - gp) / d + 4)
    s = 0.0 if mx == 0 else d / mx
    return h, s, mx


for r, g, b in [(120, 200, 80), (200, 100, 50), (90, 90, 90)]:
    Y, Cb, Cr = ycbcr(r, g, b)
    H, S, V = hsv(r, g, b)
    print("RGB(%3d,%3d,%3d) Y=%6.2f Cb=%6.2f Cr=%6.2f | H=%5.1f S=%.2f V=%.2f | ortalama=%6.2f"
          % (r, g, b, Y, Cb, Cr, H, S, V, (r + g + b) / 3))
